  t('<b>More detail</b>', t('<b>Union (343-344)</b>', 'Official Language Commission <b>1955</b> under <b>B.G. Kher</b> (report 1956)', 'Parliament committee under <b>Gobind Ballabh Pant</b> examined it <b>1957</b>; second commission due <b>1960</b> never appointed', 'Constitution asked for commission at 5 and 10 years, members for Eighth Schedule languages; Parliament committee of <b>30</b> (<b>20 LS, 10 RS</b>)'), t('<b>States (345-347)</b>', 'English continues until legislature adopts a language; choice not limited to Eighth Schedule', 'two or more states may use Hindi between themselves', 'Hindi sent to non-Hindi state needs English translation'), t('<b>Courts and laws (348-349)</b>', 'state legislature may prescribe another language for its Acts and rules; English translation must be published', '1963 Act: Hindi translations of President-published Acts authoritative; every Bill comes with Hindi translation', 'No Hindi provision for SC: hears English only', '<b>Authorised Translations (Central Laws) Act, 1973</b>: translations in Eighth Schedule languages (not Hindi) authoritative'), t('<b>Special (350-351)</b>', '<b>350A, 350B</b> added by <b>7th Am (1956)</b> on States Reorganisation Commission advice', 'Art 351: enrich Hindi from <b>Hindustani</b> and Eighth Schedule languages, vocabulary mainly from Sanskrit'), w=24),
