  mn('T-S-T-K-M-O (handout)', '“<b>T</b>hese <b>S</b>cripts <b>T</b>ell <b>K</b>nowledge, <b>M</b>any <b>O</b>ld.” Five added: <b>M</b>arathi, <b>P</b>ali, <b>P</b>rakrit, <b>A</b>ssamese, <b>B</b>engali.'),
  bx('ye', '<b>Source conflicts:</b> Mains section lists <b>six</b> classical languages; Recent Trends says the October 2024 Cabinet decision made <b>11</b>. Use <b>11</b>. Lakshmikanth counts six (older list).'),
