  mn('19-43-IX-B', '<b>19(1)(c)</b> right · <b>43-B</b> directive · <b>Part IX-B</b> (243-ZH to ZT) · State List <b>Entry 32</b> · Union List <b>Entry 44</b> · <b>21</b> directors · <b>6 months</b> for supersession, audit, AGM, returns'),
